<section class="mt-7 flex items-end justify-between"><div><h2 class="text-xl font-extrabold"><?= $type==='reseller'?'Reseller accounts':'Customer accounts' ?></h2><p class="text-sm text-[#78908c]">Assign packages and control account access.</p></div><a href="<?= base_url('admin/accounts') ?>" class="btn btn-primary">Create account</a></section>
<section class="card mt-6 overflow-x-auto p-5"><table class="w-full min-w-[900px] text-left text-sm"><thead class="text-[10px] uppercase text-[#879e9a]"><tr><th class="pb-3">Account</th><th>Company</th><th>Status</th><th>Package</th><th>Access</th></tr></thead><tbody class="divide-y divide-[#dbeae7]"><?php foreach($rows as$row): ?><tr><td class="py-4 font-bold"><?= esc(trim($row['first_name'].' '.$row['last_name'])) ?><p class="text-xs font-normal text-[#78908c]"><?= esc($row['email']) ?></p></td><td><?= esc($row['company_name']?:'—') ?></td><td><span class="rounded-full px-2 py-1 text-xs font-bold <?= $row['status']==='active'?'bg-[#dff4e9] text-[#25775f]':'bg-[#f8e6df] text-[#a4573a]' ?>"><?= esc($row['status']) ?></span></td><td><form action="<?= base_url('admin/users/'.$row['uuid'].'/plan') ?>" method="post" class="flex gap-2"><?= csrf_field() ?><select name="plan_id" class="field min-w-44" required><option value="">Choose package</option><?php foreach($plans as$p): ?><option value="<?= $p['id'] ?>" <?= (int)$row['plan_id']===(int)$p['id']?'selected':'' ?>><?= esc($p['name']) ?></option><?php endforeach ?></select><button class="btn shadow-soft">Assign</button></form></td><td><form action="<?= base_url('admin/users/'.$row['uuid'].'/status') ?>" method="post"><?= csrf_field() ?><button class="btn shadow-soft <?= $row['status']==='active'?'text-[#a4573a]':'text-[#25775f]' ?>"><?= $row['status']==='active'?'Disable':'Activate' ?></button></form></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="5" class="py-10 text-center text-[#78908c]">No accounts yet.</td></tr><?php endif ?></tbody></table></section>
